//! 📥️ The admitted command receipt owns original wire pages and one authentic registered-row lease.
use super::super::AdmittedToolCommand;
use semio_framework_plugin_job::{original_declared_tools::{DeclaredToolRegistrationAlias,DeclaredToolRole},reserved_jobs::QualifiedToolProof};
use semio_framework_plugin_decl_app::{ArtifactApp,tool_contract::ToolOwnerWitness};
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::RetainedCloneClose};
use semio_framework::action_bus::RetainedToolWireInput;
use std::mem::{ManuallyDrop,size_of};
/// 🧳️ Canonical receipt strings are born separately and copied from the retained original registration in bounded fragments.
pub struct OriginalCommandAdmission{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,verb:(usize,usize),registration:ManuallyDrop<Option<DeclaredToolRegistrationAlias>>,wire:ManuallyDrop<Option<RetainedToolWireInput>>,strings:ManuallyDrop<[Option<String>;4]>,field:usize,offset:usize,phase:u8,closing:bool,retirement:RetainedCloneClose}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native command admission lost its original registered row, wire, verb or decoder")}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn original(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
const META:usize=size_of::<(usize,usize,u8)>();
impl OriginalCommandAdmission{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()+2*size_of::<Option<DeclaredToolRegistrationAlias>>()+2*size_of::<Option<RetainedToolWireInput>>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 /// 🌱️ The same declared registration lease and sealed raw pages enter before any receipt string allocation.
 pub fn admit<A:ArtifactApp>(registration:&mut Option<DeclaredToolRegistrationAlias>,wire:&mut Option<RetainedToolWireInput>,verb:&str,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let row=registration.as_ref().ok_or_else(invalid)?;let input=wire.as_ref().ok_or_else(invalid)?;if row.owner!=ToolOwnerWitness::of::<A>()||row.key.tool_id.len()!=verb.len()||!input.original_is_sealed()||input.declared_bytes()>row.contract.max_raw_wire_bytes||row.contract.max_decoded_items<1{return Err(invalid().into())}let d=Self::birth_demands();let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;admit_original_construction(cx,output,original(d),|control|{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::write(Box::new_uninit(),Self{binding,decoder,body,verb:(verb.as_ptr()as usize,verb.len()),registration:ManuallyDrop::new(registration.take()),wire:ManuallyDrop::new(wire.take()),strings:ManuallyDrop::new([None,None,None,None]),field:0,offset:0,phase:0,closing:false,retirement:Default::default()}),receipt(d)))})}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn text<'a>(&'a self,verb:&'a str)->Result<&'a str,ValueError>{if self.verb!=(verb.as_ptr()as usize,verb.len()){return Err(invalid())}let row=self.registration.as_ref().ok_or_else(invalid)?;match self.field{0=>Ok(verb),1=>Ok(&row.key.controller_id),2=>Ok(&row.key.tool_id),3=>Ok(&row.schema_id),_=>Err(invalid())}}
 /// 🔎️ A retained admission exposes only equality against its genuine registration while control retries.
 pub fn matches_registered_action(&self,action:&str)->bool{self.registration.as_ref().is_some_and(|row|row.key.tool_id==action)}
 pub fn ready(&self)->bool{!self.closing&&self.field==4&&self.phase==0}
 pub fn demands(&self,verb:&str)->Result<RetirementDemand,ValueError>{if self.verb!=(verb.as_ptr()as usize,verb.len()){return Err(invalid())}if self.closing{return self.close_demands()}if self.ready(){return self.take_demands()}let text=self.text(verb)?;let mut d=if self.phase==0{RetirementDemand{copy_bytes:2*size_of::<Option<String>>(),capacity_bytes:text.len(),depth:1,..Default::default()}}else{let mut end=(self.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1}RetirementDemand{copy_bytes:size_of::<String>()+(end-self.offset)*(if self.field==0{2}else{1}),depth:1,..Default::default()}};d.copy_bytes+=META;Ok(d)}
 /// ✍️ Original UTF-8 metadata copies into its final receipt allocation at most sixty-four bytes per turn.
 pub fn advance(&mut self,verb:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;let d=self.demands(verb)?;if self.closing{return Err(invalid().into())}if self.ready(){return Ok(true)}let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{if self.phase==0{let mut value=String::new();value.try_reserve_exact(self.text(verb)?.len()).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"native command receipt text backing refused"))?;self.strings[self.field]=Some(value);self.phase=1;}else{let row=self.registration.as_ref().ok_or_else(invalid)?;let text=match self.field{0=>verb,1=>row.key.controller_id.as_str(),2=>row.key.tool_id.as_str(),3=>row.schema_id.as_str(),_=>return Err(invalid())};let length=text.len();let mut end=(self.offset+64).min(length);while !text.is_char_boundary(end){end-=1}if self.field==0&&text.as_bytes()[self.offset..end]!=row.key.tool_id.as_bytes()[self.offset..end]{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"native command verb differs from its authentic registered tool"))}self.strings[self.field].as_mut().ok_or_else(invalid)?.push_str(&text[self.offset..end]);self.offset=end;if self.offset==length{self.field+=1;self.offset=0;self.phase=0;}}Ok(((),receipt(d)))})?;Ok(self.ready())}
 pub fn take_demands(&self)->Result<RetirementDemand,ValueError>{if !self.ready()||self.strings.iter().any(Option::is_none)||self.registration.is_none()||!self.wire.as_ref().is_some_and(RetainedToolWireInput::original_is_sealed){return Err(invalid())}Ok(header::<(AdmittedToolCommand,AdmittedToolCommand,[Option<String>;4],u8)>())}
 /// 🤝️ The canonical receipt takes its genuine proof lease, final metadata allocations and unchanged original raw-page owner together.
 pub fn take_into(&mut self,output:&mut Option<AdmittedToolCommand>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;let d=self.take_demands()?;admit_original_construction(cx,output,original(d),|_|{let row=self.registration.as_ref().ok_or_else(invalid)?;let role=row.row_key().role();let contract=row.contract;let factory_type_id=row.factory_type_id;let factory_type_name=row.factory_type_name;let registration=self.registration.take().expect("original admission proof was preflighted");let proof=match role{DeclaredToolRole::App=>QualifiedToolProof::AppOwned(registration),DeclaredToolRole::Framework=>QualifiedToolProof::FrameworkOwned(registration),DeclaredToolRole::Bounded=>unreachable!("registration lease excludes bounded role")};let verb=self.strings[0].take().expect("original admission verb was preflighted");let controller_id=self.strings[1].take().expect("original admission controller was preflighted");let tool_id=self.strings[2].take().expect("original admission tool was preflighted");let schema_id=self.strings[3].take().expect("original admission schema was preflighted");let raw_wire=self.wire.take().expect("original admission wire was preflighted");self.phase=2;Ok((AdmittedToolCommand{verb,proof,wire_admission:semio_framework::ToolWireAdmission{key:semio_framework::ToolFactoryKey{controller_id,tool_id},factory_type_id,factory_type_name,schema_id,contract},decoded_items:1,raw_wire},receipt(d)))})}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if let Some(index)=self.strings.iter().position(Option::is_some){return self.retirement.next_owner_demands::<String>(self.strings[index].is_some(),&None,self.body)}if self.wire.is_some(){return self.retirement.next_owner_demands::<RetainedToolWireInput>(true,&None,self.body)}if self.registration.is_some(){return self.retirement.next_owner_demands::<DeclaredToolRegistrationAlias>(true,&None,self.body)}Ok(Default::default())}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands()?;close_original_retained_step(cx,d,|g|{if !self.closing{self.closing=true;return Ok(RetainedCloneStep::Progress(receipt(d)))}if !self.retirement.is_empty(){return self.retirement.select(self.body)?.step(g)}if let Some(index)=self.strings.iter().position(Option::is_some){return Ok(self.retirement.begin_granted(&mut self.strings[index],g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.wire.is_some(){return Ok(self.retirement.begin_granted(&mut self.wire,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.registration.is_some(){return Ok(self.retirement.begin_granted(&mut self.registration,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}Ok(RetainedCloneStep::Complete(Default::default()))})?;Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.registration.is_none()&&self.wire.is_none()&&self.strings.iter().all(Option::is_none)&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalCommandAdmission{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native command admission must hand off or close every original receipt owner")}}
